#include <iostream>
#include <iomanip>
#include <string>

class CommissionEmployee {
public:
    CommissionEmployee(const std::string& first, const std::string& last,
                       const std::string& ssn, double sales, double rate)
        : firstName(first), lastName(last), socialSecurityNumber(ssn),
          grossSales(sales), commissionRate(rate) {}

    virtual ~CommissionEmployee() = default;

    virtual double earnings() const {
        return commissionRate * grossSales;
    }

    virtual void print() const {
        std::cout << "commission employee: " << firstName << ' ' << lastName
                  << "\nsocial security number: " << socialSecurityNumber
                  << "\ngross sales: " << grossSales
                  << "\ncommission rate: " << commissionRate;
    }

private:
    std::string firstName;
    std::string lastName;
    std::string socialSecurityNumber;
    double grossSales;
    double commissionRate;
};

class BasePlusCommissionEmployee : public CommissionEmployee {
public:
    BasePlusCommissionEmployee(const std::string& first, const std::string& last,
                               const std::string& ssn, double sales, double rate, double salary)
        : CommissionEmployee(first, last, ssn, sales, rate), baseSalary(salary) {}

    virtual double earnings() const override {
        return baseSalary + CommissionEmployee::earnings();
    }

    virtual void print() const override {
        std::cout << "base-salaried ";
        CommissionEmployee::print();
        std::cout << "\nbase salary: " << baseSalary;
    }

private:
    double baseSalary;
};

int main() {
    std::cout << std::fixed << std::setprecision(2);

    CommissionEmployee ce("Sue", "Jones", "222-22-2222", 10000.0, 0.06);
    BasePlusCommissionEmployee bpce("Bob", "Lewis", "333-33-3333", 5000.0, 0.04, 300.0);

    CommissionEmployee* ptr = &ce;
    std::cout << "Base pointer to Base object:\n";
    ptr->print();
    std::cout << "\nearnings: $" << ptr->earnings() << "\n\n";

    ptr = &bpce; // Polymorphic binding
    std::cout << "Base pointer to Derived object (dynamic binding):\n";
    ptr->print();
    std::cout << "\nearnings: $" << ptr->earnings() << '\n';

    return 0;
}

#include <iostream>
#include <memory>
#include <string>

class ResourceOwner {
public:
    ResourceOwner() { std::cout << "ResourceOwner constructed\n"; }
    // Essential virtual destructor
    virtual ~ResourceOwner() { std::cout << "ResourceOwner destroyed\n"; }

    virtual void process() const {
        std::cout << "ResourceOwner processing\n";
    }
};

class CustomResource final : public ResourceOwner {
public:
    CustomResource() : buffer(new int[10]) {
        std::cout << "CustomResource allocated dynamic buffer\n";
    }

    ~CustomResource() override {
        delete[] buffer;
        std::cout << "CustomResource buffer freed\n";
    }

    // Method cannot be overridden further (and class is also final)
    void process() const override final {
        std::cout << "CustomResource processing securely\n";
    }

private:
    int* buffer;
};

int main() {
    std::cout << "--- Deleting via base pointer ---\n";
    ResourceOwner* ptr = new CustomResource();
    ptr->process();
    delete ptr; // Properly invokes ~CustomResource(), then ~ResourceOwner()

    std::cout << "--- Done ---\n";
    return 0;
}
